      transition={{ duration: 0.5, delay: index * 0.1, ease: 'easeOut' as const }}
      className={`group relative bg-card rounded-2xl overflow-hidden shadow-sm hover:-translate-y-1.5 hover:shadow-lg transition-all duration-300 ${
