import { useLoaderData } from 'react-router-dom';
import { useState } from 'react';
import { motion } from 'motion/react';
import { Helmet } from '@dr.pogodin/react-helmet';
import { SlidersHorizontal } from 'lucide-react';
import type { Product } from '../server/api/products/GET';

interface LoaderData {
  products: Product[];
}

type Category = 'all' | 'pottery' | 'textiles' | 'woodwork' | 'jewelry';

const categories: { value: Category; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'pottery', label: 'Pottery' },
  { value: 'textiles', label: 'Textiles' },
  { value: 'woodwork', label: 'Woodwork' },
  { value: 'jewelry', label: 'Jewelry' },
];

const categoryColors: Record<string, string> = {
  pottery: 'bg-amber-100 text-amber-800',
  textiles: 'bg-emerald-100 text-emerald-800',
  woodwork: 'bg-orange-100 text-orange-800',
  jewelry: 'bg-yellow-100 text-yellow-800',
};

function ProductCard({ product, index }: { product: Product; index: number }) {
  return (
    <motion.article
      initial={{ opacity: 0, y: 24 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: index * 0.07, ease: 'easeOut' as const }}
      className="group bg-card rounded-2xl overflow-hidden shadow-sm hover:-translate-y-1.5 hover:shadow-lg transition-all duration-300"
    >
      <div className="aspect-square overflow-hidden">
        <img
          src={product.image}
          alt={product.name}
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
          loading="lazy"
        />
      </div>
      <div className="p-5">
        <span
          className={`inline-block text-xs font-medium px-2.5 py-1 rounded-full mb-3 capitalize ${
            categoryColors[product.category] ?? 'bg-muted text-muted-foreground'
          }`}
        >
          {product.category}
        </span>
        <h3 className="font-heading font-semibold text-foreground text-base leading-snug mb-1">
          {product.name}
        </h3>
        <p className="text-muted-foreground text-sm leading-relaxed mb-3 line-clamp-2">
          {product.description}
        </p>
        <div className="flex items-center justify-between">
          <span className="text-primary font-bold text-lg">${product.price}</span>
          <button className="text-xs font-medium px-4 py-1.5 rounded-full border border-primary text-primary hover:bg-primary hover:text-primary-foreground transition-colors duration-200">
            Add to Cart
          </button>
        </div>
      </div>
    </motion.article>
  );
}

export default function ProductsPage() {
  const { products } = useLoaderData() as LoaderData;
  const [activeCategory, setActiveCategory] = useState<Category>('all');

  const filtered =
    activeCategory === 'all'
      ? products
      : products.filter((p) => p.category === activeCategory);

  return (
    <>
      <Helmet>
        <title>Our Collection — Artisan Goods Co.</title>
        <meta
          name="description"
          content="Browse our full collection of handcrafted pottery, textiles, woodwork, and jewelry. Each piece made by independent artisans."
        />
      </Helmet>

      {/* Page Header */}
      <section className="py-16 md:py-20 bg-muted">
        <div className="container mx-auto px-6">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            <p className="text-primary text-sm font-medium tracking-widest uppercase mb-3">
              Handmade Goods
            </p>
            <h1 className="font-heading text-4xl md:text-5xl font-bold text-foreground mb-4">
              Our Collection
            </h1>
            <p className="text-muted-foreground text-lg max-w-xl">
              Every piece is made by hand, with care. Browse our full range of artisan goods across four categories.
            </p>
          </motion.div>
        </div>
      </section>

      {/* Filters + Grid */}
      <section className="py-12 bg-background">
        <div className="container mx-auto px-6">
          {/* Filter Bar */}
          <div className="flex items-center gap-3 mb-10 flex-wrap">
            <SlidersHorizontal size={16} className="text-muted-foreground shrink-0" />
            <div className="flex gap-2 flex-wrap">
              {categories.map((cat) => (
                <button
                  key={cat.value}
                  onClick={() => setActiveCategory(cat.value)}
                  className={`px-5 py-2 rounded-full text-sm font-medium transition-all duration-200 ${
                    activeCategory === cat.value
                      ? 'bg-primary text-primary-foreground shadow-sm'
                      : 'bg-muted text-foreground/70 hover:bg-muted/80 hover:text-foreground'
                  }`}
                >
                  {cat.label}
                  {cat.value !== 'all' && (
                    <span className="ml-1.5 text-xs opacity-60">
                      ({products.filter((p) => p.category === cat.value).length})
                    </span>
                  )}
                </button>
              ))}
            </div>
            <span className="ml-auto text-sm text-muted-foreground">
              {filtered.length} {filtered.length === 1 ? 'piece' : 'pieces'}
            </span>
          </div>

          {/* Product Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filtered.map((product, i) => (
              <ProductCard key={product.id} product={product} index={i} />
            ))}
          </div>

          {filtered.length === 0 && (
            <div className="text-center py-24 text-muted-foreground">
              <p className="text-lg">No products found in this category.</p>
            </div>
          )}
        </div>
      </section>
    </>
  );
}

