import type { Product } from '../server/api/products/GET';

export type { Product };

/**
 * Resolves the correct base URL for API calls.
 * - In the browser, relative paths work fine.
 * - On the server (SSR / route loaders), we need an absolute URL.
 *   The PORT env var matches what Express listens on; fall back to 3000.
 */
function apiBase(): string {
  if (typeof window !== 'undefined') return '';
  const port = process.env.PORT ?? '3000';
  return `http://localhost:${port}`;
}

/**
 * Fetch the full list of products from the API.
 * Returns an empty array on any network or HTTP error so callers
 * don't need to handle exceptions for the common degraded-state case.
 */
export async function fetchProducts(): Promise<Product[]> {
  try {
    const res = await fetch(`${apiBase()}/api/products`);
    if (!res.ok) {
      console.error(`products.service: GET /api/products returned ${res.status}`);
      return [];
    }
    return (await res.json()) as Product[];
  } catch (err) {
    console.error('products.service: fetch failed', err);
    return [];
  }
}

/**
 * Return only the products flagged as featured.
 */
export async function fetchFeaturedProducts(): Promise<Product[]> {
  const all = await fetchProducts();
  return all.filter((p) => p.featured);
}

/**
 * Return products filtered by category.
 */
export async function fetchProductsByCategory(
  category: Product['category'],
): Promise<Product[]> {
  const all = await fetchProducts();
  return all.filter((p) => p.category === category);
}

import { RouteObject } from 'react-router-dom';
import { lazy } from 'react';
import HomePage from './pages/index';
import ProductsPage from './pages/products';
import AboutPage from './pages/about';
import { fetchProducts } from './services/products';
// Eager import so renderToString doesn't hit a Suspense boundary on 404 routes
// and abort to client rendering. The prod 404 page is tiny; the dev-tools
// variant stays lazy because it pulls in dev-only code we don't want in
// production bundles.
import ProdNotFoundPage from './pages/_404';

const NotFoundPage = import.meta.env.DEV
  ? lazy(() => import('../dev-tools/src/PageNotFound'))
  : ProdNotFoundPage;

export const routes: RouteObject[] = [
  {
    path: '/',
    element: <HomePage />,
    loader: async () => {
      const products = await fetchProducts();
      return { products };
    },
  },
  {
    path: '/products',
    element: <ProductsPage />,
    loader: async () => {
      const products = await fetchProducts();
      return { products };
    },
  },
  {
    path: '/about',
    element: <AboutPage />,
  },
  {
    path: '*',
    element: <NotFoundPage />,
  },
];

// Types for type-safe navigation
export type Path = '/' | '/products' | '/about';

export type Params = Record<string, string | undefined>;

